			function setTaskwkSeCd() {
			    var voDsUseTaskSysSeCd = app.lookup("dsUseTaskSysSeCd");
			    var vnRowCnt = voDsUseTaskSysSeCd.getRowCount();
			    
			    if (vnRowCnt == 0) return false;
			    
			    var vaTaskwkSeNms = [];
			    
			    for (var i = 0; i < vnRowCnt; i++) {
			        var vsTaskwkSeNm = voDsUseTaskSysSeCd.getValue(i, "UNT_TASKWK_SE_NM");
			        vaTaskwkSeNms.push(vsTaskwkSeNm);
			    }
			    
			    var vsTaskwkSeNms = vaTaskwkSeNms.toString().replace(/ /g, "");
			    var voDsBrdDtlList = app.lookup("dsBoardDtlList");
			    voDsBrdDtlList.setValue(0, "UNT_TASKWK_SE_NMS", vsTaskwkSeNms);
			    voDsBrdDtlList.setRowStateAll(cpr.data.tabledata.RowState.UNCHANGED);
			}

