			                if (ValueUtil.isNull(vnBrdSeq)) { // 파일만 저장할 경우 시퀀스 번호를 받아올 수 없음
			                    vnBrdSeq = mnBrdSeq;
			                }
			                
			                util.DataMap.setValue(app, "dmParam", "strBbscttEsntalNo", vnBrdSeq);
			                
			                // 목록 리스트와 저장 리스트를 구분지어 사용하기 때문에 옵션으로 적용하는 _findRowCondition 직접적용
