			/**
			 * 댓글의 수정버튼 클릭시 발생 이벤트
			 */
			function onBtnCmntClick( /*cpr.events.CMouseEvent*/ e) {
			    /**@type cpr.controls.Button*/
			    var vcBtnCmnt = e.control;
			    var vnCmntNo = vcBtnCmnt.userData("cmntNo");
			    var vsType = vcBtnCmnt.userData("type");
			    
			    var voDsBrdDtlCmntList = app.lookup("dsBoardDtlCmntList");
			    var vcGrpBtnCmnt = vcBtnCmnt.getParent(); // 버튼영역 그룹   
			    var vcGrpCmnt = vcGrpBtnCmnt.getParent(); // 댓글 영역 그룹
			    
			    var vcTxaCmnt = null;
			    var vcFileUpload = null;
			    
			    vcGrpCmnt.getChildren().forEach(function(ctrl) {
			        if (ctrl instanceof udc.cmn.cmnAutoHeightTextArea) {
			            vcTxaCmnt = ctrl;
			        } else if (ctrl instanceof udc.cmn.cmnMultiFileUpload) {
			            vcFileUpload = ctrl;
			        }
			    });
			    
			    if (vsType == "update") { // 수정버튼
			        vcGrpCmnt.readOnly = false;
			        
			        // 수정, 삭제버튼 숨김 저장버튼 활성화(저장, 삭제 동작시 재구성하기 때문에 초기화하지 않는다)
			        vcGrpBtnCmnt.getLayout().setRowVisible(1, false);
			        vcGrpBtnCmnt.getLayout().setRowVisible(2, false);
			        vcGrpBtnCmnt.getLayout().setRowVisible(3, true);
			        vcGrpBtnCmnt.getLayout().setRowVisible(4, true);
			        
			        // 파일 업로드 표시
			        vcFileUpload.showFileBtn = false;
			        
			        // 텍스트 에리어 포커스
			        vcTxaCmnt.focus();
			        
			    } else if (vsType == "restore") { // 취소 버튼
			        
			        if (_cmntIsModified(vnCmntNo, vcFileUpload, vcTxaCmnt)) {
			            
			            util.Msg.confirm(app, "CRM-M003", "답변", function() {
			                var vnTargetIdx = voDsBrdDtlCmntList.findFirstRow("UNITY_CMNT_SN == '" + vnCmntNo + "'").getIndex();
			                voDsBrdDtlCmntList.revertRow(vnTargetIdx);
			                vcFileUpload.getFiles();
			                
			                vcGrpCmnt.readOnly = true;
			                vcFileUpload.showFileBtn = true;
			                
			                vcGrpBtnCmnt.getLayout().setRowVisible(1, true);
			                vcGrpBtnCmnt.getLayout().setRowVisible(2, true);
			                vcGrpBtnCmnt.getLayout().setRowVisible(3, false);
			                vcGrpBtnCmnt.getLayout().setRowVisible(4, false);
			            });
			        } else {
			            vcGrpCmnt.readOnly = true;
			            vcFileUpload.showFileBtn = true;
			            
			            vcGrpBtnCmnt.getLayout().setRowVisible(1, true);
			            vcGrpBtnCmnt.getLayout().setRowVisible(2, true);
			            vcGrpBtnCmnt.getLayout().setRowVisible(3, false);
			            vcGrpBtnCmnt.getLayout().setRowVisible(4, false);
			        }
			        
			    } else { // 저장, 삭제 버튼
			        var vnTargetIdx = voDsBrdDtlCmntList.findFirstRow("UNITY_CMNT_SN == '" + vnCmntNo + "'").getIndex();
			        
			        if (vsType == "delete") {
			            util.Msg.confirm(app, "CRM-M016", "댓글", function() {
			                voDsBrdDtlCmntList.deleteRow(vnTargetIdx);
			                
			                doCmntSave();
			            });
			            
			        } else if (vsType = "save") {
			            var newTextVal = vcTxaCmnt.value;
			            voDsBrdDtlCmntList.setValue(vnTargetIdx, "UNITY_CMNT_CN", newTextVal);
			            
			            // 댓글 저장 서브미션 호출
			            vcFileUpload.send(function() {
			                
			                voDsBrdDtlCmntList.setValue(vnTargetIdx, "ATFINO", vcFileUpload.atfino);
			                
			                doCmntSave();
			            });
			        }
			    }
			}

			/**
			 * 댓글 저장 서브미션
			 */
			function doCmntSave(pbInsertYn) {
			    
			    util.Submit.send(app, "subCmntSave", function(pbSuccess) {
			        if (pbSuccess) {
			            if (pbInsertYn == true) {
			                app.lookup("cmnAutoTxaCmt").value = "";
			                
			                app.lookup("cmnMultifileupload2").removeAllFiles();
			            }
			            doList("save");
			        }
			    });
			}

			//=================================================================================
			// [Control Event Function]
			//=================================================================================

			/*
			 * 루트 컨테이너에서 init 이벤트 발생 시 호출.
			 * 앱이 최초 구성될 때 발생하는 이벤트 입니다.
			 */
			function onBodyInit(e) {
			    
			    // 로그인 사용자 정보 
			    var voUserInfo = util.Auth.getUserInfo(app).getDatas();
			    app.lookup("dmUserInfo").build(voUserInfo);
			    
			    // TODO 관리자 권한(임시 테스트를 위해 역할 구분 코드 활용, 1: 총괄관리자, 2 : 관리자, 3 : 사용자)
			    var vsGroupAuthrtSeCd = voUserInfo["GROUP_AUTHRT_SE_CD"].substr(1, 2);
			    
			    if (vsGroupAuthrtSeCd == "00" || vsGroupAuthrtSeCd == "10") { // 총괄 관리자             
			        msAdminType = "generalAdmin";
			        
			    } else if (vsGroupAuthrtSeCd == "20") { // 관리자        
			        msAdminType = "admin";
			        
			    } else { // 사용자
			        msAdminType = "user";
			    }
			    
			    // 답변 등록 날짜 현재 일자 구성(단순 표시용);
			    app.lookup("optCmntWriDtVal").value = moment().format("YYYY-MM-DD");
			}

