			/*
			 * "삭제" 버튼(btnDelete)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnDeleteClick( /* cpr.events.CMouseEvent */ e) {
			    
			    util.Msg.confirm(app, "CRM-M002", null, function() {
			        
			        var voDsBrdDtlList = app.lookup("dsBoardDtlList");
			        
			        // 기본 게시글 삭제
			        voDsBrdDtlList.deleteRow(0);
			        
			        // 저장
			        doSave("delete");
			    });
			}

			/*
			 * "저장" 버튼(btnUpdAdd4)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick( /* cpr.events.CMouseEvent */ e) {
			    
			    // 공지단위 시스템 조건 체크 
			    var vaUnDelRowIdxs = app.lookup("dsUseTaskSysSeCd").getRowStatedIndices(cpr.data.tabledata.RowState.UNCHANGED | cpr.data.tabledata.RowState.INSERTED);
			    if (vaUnDelRowIdxs.length == 0) {
			        util.Msg.alert(app, "하나 이상의 단위 시스템을 선택해야 합니다.");
			        return false;
			    }
			    
			    // 변경 사항 체크
			    if (!_isModified()) {
			        util.Msg.alert(app, "INF-M006");
			        return false;
			    }
			    
			    // 유효성 체크
			    if (!util.validate(app, "grpBoardDtl")) return;
			    
			    var vcHtmlEdit = app.lookup("cmnHtmlEditor");
			    var vcfld = app.lookup("cmnMultifileupload");
			    
			    // 에디터 값 데이터 셋 저장
			    var vsContent = vcHtmlEdit.getValue();
			    if (ValueUtil.isNull(vsContent)) {
			        util.Msg.alert(app, "WRN-M001", "내용");
			        return false;
			    }
			    
			    if (vsContent.length > 20008) {
			        util.Msg.alert(app, "내용은 최대 20,000자 까지 입력 가능합니다.\n (현재 글자수: " + (vsContent.length - 8) + "자)");
			        return false;
			    }
			    util.DataSet.setValue(app, "dsBoardDtlList", 0, "UNITY_BBSCTT_CN", vsContent);
			    
			    vcfld.send(doSave);
			    
			}

			/*
			 * "수정" 버튼(btnUpdate)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnUpdateClick( /* cpr.events.CMouseEvent */ e) {
			    
			    app.getContainer().scrollTo(0, 0);
			    
			    setBrdDtlBatCrud("UPDATE");
			}

			/*
			 * "취소" 버튼(btnRestore)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnRestoreClick(e) {
			    var btnRestore = e.control;
			    
			    var voDsBrdDtlList = app.lookup("dsBoardDtlList");
			    var vnRowState = voDsBrdDtlList.getRowState(0);
			    
			    // TODO 취소 유효성 처리
			    var vbIsModified = false;
			    var vsEditVal = app.lookup("cmnHtmlEditor").getValue();
			    
			    if (vnRowState == 2) { // 신규등록시 제목, 내용만 변경사항 체크
			        
			        if (!ValueUtil.isNull(vsEditVal)) { // 내용 체크
			            vbIsModified = true;
			        } else if (!ValueUtil.isNull(app.lookup("ipbTitle").value)) { // 제목 체크
			            vbIsModified = true;
			        }
			        
			        if (vbIsModified) {
			            // 신규등록 화면에서 취소시 화면전환
			            util.Msg.confirm(app, "CRM-M003", app.lookup("grpBoardDtl").fieldLabel, function() {
			                
			                selectMdiListItem();
			            });
			        } else {
			            selectMdiListItem();
			        }
			        
			    } else {
			        
			        if (_isModified()) {
			            util.Msg.confirm(app, "CRM-M003", app.lookup("grpBoardDtl").fieldLabel, function() {
			                
			                // 초기값 전환
			                voDsBrdDtlList.revert();
			                app.lookup("dsUseTaskSysSeCd").revert();
			                app.lookup("cmnMultifileupload").getFiles();
			                
			                util.Control.redraw(app, "grpBoardDtl");
			                
			                setBrdDtlBatCrud("READ");
			            });
			        } else {
			            setBrdDtlBatCrud("READ");
			        }
			        
			    }
			}

			/*
			 * 루트 컨테이너에서 property-change 이벤트 발생 시 호출.
			 * 앱의 속성이 변경될 때 발생하는 이벤트 입니다.
			 */
			function onBodyPropertyChange(e) {
			    
			    // 기본구성 콤포박스 셋팅
			    if (e.property == "initValue") {
			        msBbscttTypeSeCd = e.newValue["TYPE_CD"];
			        msTaskwkSeCd = e.newValue["TASKWK_SE_CD"];
			        
			        app.lookup("dsCmbCtgrybSeCd").build(e.newValue["CTGRYB_SE_CD_DATAS"]);
			        app.lookup("dsCmbTaskSysSeCd").build(e.newValue["TASK_SYS_SE_CD_DATAS"]);
			        
			        util.Control.redraw(app, ["cmbCtgrybSeCd", "cmbTaskSysSeCd"]);
			    }
			}

			/*
			 * 콤보 박스에서 selection-change 이벤트 발생 시 호출.
			 * ComboBox Item을 선택하여 선택된 값이 저장된 후에 발생하는 이벤트.
			 */
			function onCmbCtgrybSeCdSelectionChange(e) {
			    var cmbCtgrybSeCd = e.control;
			    
			    if (msAdminType == "user") return false;
			    
			    var voDsCmbTaskSysSeCd = app.lookup("dsCmbTaskSysSeCd");
			    var voDsUseTaskSysSeCd = app.lookup("dsUseTaskSysSeCd");
			    
			    var vaTaskwkSeNms = [];
			    if (cmbCtgrybSeCd.value == "006001") { // 시스템 선택할 경우 전체 공지       
			        
			        voDsCmbTaskSysSeCd.getRowDataRanged().forEach(function(row) {
			            var voFindRow = voDsUseTaskSysSeCd.findFirstRow("UNT_TASKWK_SE_CD == '" + row["CMMNS_CD_VALUE"] + "'");
			            vaTaskwkSeNms.push(row["CMMNS_CD_VALUE_NM"]);
			            
			            if (!voFindRow) {
			                voDsUseTaskSysSeCd.addRowData({
			                    UNT_TASKWK_SE_CD: row["CMMNS_CD_VALUE"]
			                });
			            }
			        });
			        
			    } else {
			        
			        for (var i = 0; i < voDsUseTaskSysSeCd.getRowCount(); i++) {
			            
			            if (voDsUseTaskSysSeCd.getValue(i, "UNT_TASKWK_SE_CD") == msTaskwkSeCd) {
			                var vsTaskwkNm = voDsCmbTaskSysSeCd.findFirstRow("CMMNS_CD_VALUE =='" + msTaskwkSeCd + "'").getValue("CMMNS_CD_VALUE_NM")
			                vaTaskwkSeNms.push(vsTaskwkNm);
			            } else {
			                voDsUseTaskSysSeCd.realDeleteRow(i);
			                i--;
			            }
			        }
			    }
			    
			    util.DataSet.setValue(app, "dsBoardDtlList", 0, "UNT_TASKWK_SE_NMS", vaTaskwkSeNms);
			    
			}

